public interface PatientManagementSystem {


    void printPatients();

    Patient pollPatient();

    boolean addPatient(Patient patientData);
}

public class Patient {
    String name;
    String adresse;
    String krankheit;
    int alter;

    public Patient(String name, String address, String illness, int age) {
        this.name = name;
        this.adresse = address;
        this.krankheit = illness;
        this.alter = age;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getAdresse() {
        return adresse;
    }

    public void setAdresse(String adresse) {
        this.adresse = adresse;
    }

    public String getKrankheit() {
        return krankheit;
    }

    public void setKrankheit(String krankheit) {
        this.krankheit = krankheit;
    }

    public int getAlter() {
        return alter;
    }

    public void setAlter(int alter) {
        this.alter = alter;
    }
}

public class PatientManagement1 implements PatientManagementSystem {

   Patient [] patients;
   int capacity;

   public PatientManagement1(int capacity) {
      patients = new Patient[capacity];
      this.capacity = capacity;
   }

   public boolean addPatient(Patient patient) {
      for (int i = 0; i < patients.length; i++) {
         if(patients[i] == null) {
            patients[i] = patient;
            return true;
         }
      }
      System.out.println("Cannot add patient!");
      return false;
   }


   public Patient pollPatient() {
      for (int i = 0; i < patients.length; i++) {
         if(patients[i] != null) {
            Patient patient = patients[i];
            patients[i] = null;
            return patient;
         }
      }
      System.out.println("No patients");
      return null;
   }

   public void printPatients() {
      for (int i = 0; i < patients.length; i++) {
         Patient patient = patients[i];
         if(patient != null) {
            System.out.println(i + " " + patient.getName());
         }
      }
   }
}

public class ListElement {

   Patient patient; 
   ListElement nachfolger;

   public ListElement(String name, String address, String illness, int age) {
      this.patient = new Patient(name, address, illness, age); 
   }

   public ListElement(Patient patient) {
      this.patient = patient; 
   }

   public ListElement getNachfolger() {
      return nachfolger;
   }

   public void setNachfolger(ListElement nachfolger) {
      this.nachfolger = nachfolger;
   }

   public Patient getPatient() {
      return this.patient; 
   }
}

public class PatientManagement2WithNumber implements PatientManagementSystem {

    Patient [] patients;
    int capacity;
    int currentPatient;

    public PatientManagement2WithNumber(int capacity) {
        patients = new Patient[capacity];
        this.capacity = capacity;
    }


    public boolean addPatient(Patient patient) {
        for (int i = 0; i < patients.length; i++) {
            if(patients[i] == null) {
                patients[i] = patient;
                return true;
            }
        }
        System.out.println("Cannot add patient!");
        return false;
    }


    public Patient pollPatient() {
        if(patients[currentPatient] != null) {
            Patient patient = patients[currentPatient];
            patients[currentPatient] = null;
            currentPatient++;
            return patient;
        }
        System.out.println("No patients");
        return null;
    }


    public void printPatients() {
        for (int i = 0; i < patients.length; i++) {
            Patient patient = patients[i];
            if(patient != null) {
                System.out.println(i + " " + patient.getName());
            }
        }
    }
}

public class PatientManagement3WithMoveUp implements PatientManagementSystem{

    Patient [] patients;
    int capacity;

    int lastPatient;

    public PatientManagement3WithMoveUp(int capacity) {
        patients = new Patient[capacity];
        this.capacity = capacity;
    }


    public boolean addPatient(Patient patient) {
        if(patients[lastPatient] == null && lastPatient < capacity -1) {
            patients[lastPatient] = patient;
            lastPatient++;
            return true;
        } else {
            System.out.println("Cannot add patient!");
            return false;
        }
    }


    public Patient pollPatient() {
        if(patients[0] != null) {
            Patient patient = patients[0];
            for(int i = 0; i < lastPatient - 1; i++) {
                //Screen.getScreen().warte(500);
                patients[i] = patients[i+1];
            }
            lastPatient--;
            patients[lastPatient] = null;
            return patient;
        } else {
            System.out.println("No patients");
            return null;
        }
    }


    public void printPatients() {
        for (int i = 0; i < patients.length; i++) {
            Patient patient = patients[i];
            if(patient != null) {
                System.out.println(i + " " + patient.getName());
            }
        }
    }
}

public class PatientManagementWithQueue implements PatientManagementSystem {
    PatientQueue patientQueue;


    public PatientManagementWithQueue() {
        patientQueue = new PatientQueue(null);

    }


    public boolean addPatient(Patient patient) {
        return patientQueue.add(new ListElement(patient));
    }


    public Patient pollPatient() {
        return patientQueue.poll().getPatient();
    }


    public void printPatients () {
        patientQueue.printPatients();
    }
}

public class PatientQueue {

   ListElement anfang;
   ListElement ende; 

   public PatientQueue(ListElement anfang) {
      this.anfang = anfang;
   }

    /**
     * Inserts the specified element into this queue returning true upon
     * success.
     * @param patient the patient to add
     * @return true
     */
   public boolean add(ListElement patient) {
      if(anfang == null) {
         this.anfang = patient;
         this.ende = patient; 
      } else {
         ende.setNachfolger(patient);
         ende = patient; 
      }
      return true;
   }

    /**
     * Retrieves and removes the head of this queue, or returns null if
     * this queue is empty.
     * @return the head of this queue, or null if this queue is empty
     */
   public ListElement poll() {
      ListElement ret = anfang;
      if(anfang != null) {
         anfang = anfang.getNachfolger();
      }
      return ret;
   }

    /**
     * Retrieves, but does not remove, the head of this queue, or returns null
     * if this queue is empty.
     * @return the head of this queue, or null if this queue is empty
     */
   public ListElement peek() {
      return anfang;
   }

   public void printPatients() {
      ListElement tmp = anfang;
      int count = 0; 
      while (tmp != null) {
         println(count + " " + tmp.getPatient().getName());
         tmp = tmp.getNachfolger();
         count++;
      }
   }
}
